contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable {
        require(depositAmount > 0);
        require(collectAmount > depositAmount);

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(balBefore == balAfter && cBalBefore == cBalAfter);
    }

    receive() external payable {}
}

